"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[941],{5957(e){e.exports=JSON.parse('{"title":"\ud074\ub9bd\ubcf4\ub4dc\ub97c \uc798 \uc4f0\uae30 \uc704\ud55c \uc5ec\ud589","date":"2024-09-13","coverUrl":null,"html":"<h2 data-notion-block-id=\\"2c98e3ed-876f-4237-ac5a-a11e88270fcf\\" id=\\"2c98e3ed-876f-4237-ac5a-a11e88270fcf\\">\ud074\ub9bd\ubcf4\ub4dc\ub97c \uc798 \uc4f0\uae30 \uc704\ud55c \uc5ec\ud589</h2><a href=\\"https://alexharri.com/blog/clipboard\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://alexharri.com/blog/clipboard</a><p data-notion-block-id=\\"3df1a027-b63f-48cf-96fd-9edc1ecc9d02\\"><b>\uc2ec\uc724\uc12d</b>: W3C \ud074\ub9bd\ubcf4\ub4dc API\uc5d0 \ub300\ud55c \uc124\uba85\uacfc \uc5ed\uc0ac, Figma\uc640 Google Docs\uc5d0\uc11c\ub294 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ub418\ub294\uc9c0 \uc124\uba85\ud569\ub2c8\ub2e4. \ud074\ub9bd\ubcf4\ub4dc API\ub97c \ud65c\uc6a9\ud560 \uc608\uc815\uc774\ub77c\uba74 \ubcf4\uae30 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \ud639\uc740 \ub2e4\ub978 \uae30\ub2a5\uc744 \uad6c\ud604\ud560 \ub54c \ub2e4\ub978 \uc720\uba85\ud55c \uae30\uc5c5\uc5d0\uc11c \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uad6c\ud604\ud588\ub294\uc9c0 \ubcf4\ub294 \uac83\uc744 \ubc30\uc6b8 \uc218\ub3c4 \uc788\uaca0\ub124\uc694.</p><p data-notion-block-id=\\"6b65657d-76a0-4d2e-aa1c-a474e3c7dda7\\"><b>\uae40\ub300\uad00</b>: \ubcf5\uc0ac \uae30\ub2a5\uc5d0 \ub300\ud55c \ucee4\uc2a4\ud140 \uad6c\ud604\uc5d0 \ud65c\uc6a9\ud560 \uc218 \uc788\ub294 \ud0a4\uc6cc\ub4dc\ub97c \uc798 \uc124\uba85\ud55c \uae00\uc785\ub2c8\ub2e4. \uc0ac\uc6a9\uc790 \ud3b8\uc758\uc131\uc744 \uace0\ub824\ud558\uc5ec \ud074\ub9bd\ubcf4\ub4dc API\ub97c \ud65c\uc6a9\ud560 \ub54c \uc5b4\ub5a4 \uad6c\uc870\ub97c \ud1b5\ud574 \uad6c\ud604\ud560 \uac83\uc778\uc9c0 \uc5ff\ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"096bf71d-9597-449b-a7c6-9bdd69000f93\\" id=\\"096bf71d-9597-449b-a7c6-9bdd69000f93\\">\uc6d0\uc790 \uc0c1\ud0dc \uad00\ub9ac \uc0ac\uc6a9\uae30</h2><a href=\\"https://www.frontendundefined.com/posts/monthly/jotai-atomic-state-management/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.frontendundefined.com/posts/monthly/jotai-atomic-state-management/</a><p data-notion-block-id=\\"22ee6e10-7b8d-469c-849c-f7cc3aaca2ea\\"><b>\uc2ec\uc724\uc12d</b>: \uc6d0\uc790 \uc0c1\ud0dc \uad00\ub9ac \ub77c\uc774\ube0c\ub7ec\ub9ac\ub294 Recoil\uc758 \ub4f1\uc7a5\uc73c\ub85c \uc2dc\uc791\ub418\uc5c8\uc9c0\ub9cc, \ub4f1\uc7a5\ub54c\uc5d0 \ubc1b\uc740 \uad00\uc2ec\ubcf4\ub2e4\ub294 \ud604\uc7ac \uc0ac\uc6a9\uc744 \uae30\uc874 Flux \uae30\ubc18 \ub77c\uc774\ube0c\ub7ec\ub9ac\ubcf4\ub2e4 \uc0ac\uc6a9\uc774 \ub35c \ud55c \uac83 \uac19\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc0c1\ud669\uc5d0 \ub530\ub77c \uad1c\ucc2e\uc744 \uc218\ub3c4 \uc788\ub2e4\ub294 \uac83\uc744 \uac00\ubccd\uac8c \uc0ac\uc6a9\ud574\ubcf4\uba74\uc11c \uc7a5\ub2e8\uc810\uc5d0 \ub300\ud574 \uc0b4\ud3b4\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc911\uc559 \uc9d1\uc911\ud615 \uc2dc\uc2a4\ud15c\uacfc \ubd84\uc0b0 \uc2dc\uc2a4\ud15c\uc758 \ucc28\uc774\ub77c\uace0 \ubcfc \uc218\ub3c4 \uc788\uad6c\uc694.</p><p data-notion-block-id=\\"81ebb416-3022-441d-b25d-3ceb7186f791\\"><b>\uae40\ub300\uad00</b>: \uc704 \uae00\uc5d0\uc11c \uc6d0\uc790 \uc0c1\ud0dc \ub77c\uc774\ube0c\ub7ec\ub9ac Jotai\uc640 tanstack-query \uae30\ub2a5\uc5d0 \ub300\ud55c \ub9ac\ub80c\ub354\ub9c1 \uc774\uc288\ub97c \ubcf4\uba74\uc11c, \uc6d0\uc790 \uc0c1\ud0dc\uc5d0 \ub9de\ucdb0\uc11c \ub9ac\ud329\ud1a0\ub9c1\ud558\ub294 \ubd80\ubd84\uc774 \uc778\uc0c1\uc801\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \uc6d0\uc790 \uc0c1\ud0dc \uad00\ub9ac\uac00 \uc5b4\ub824\uc6c0\uc774 \uc788\uae30 \ub54c\ubb38\uc5d0 \uae00\uc4f4\uc774\ub3c4 \uc88b\uc740 \ubc29\uc2dd\uc740 \uc544\ub2c8\uae30\uc5d0 \ucd94\ucc9c\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4\uace0 \ud558\uc9c0\ub9cc, \uc0c1\ud0dc \uad00\ub9ac \ub85c\uc9c1\uc744 \uc678\ubd80\uc5d0 \ub458 \uc218 \uc788\ub294 \ud6a8\uc728\uc801\uc778 \uc774\uc810\uc774 \uc788\uc73c\ub2c8 \ubcf8\uc778\uc758 \ud504\ub85c\uc81d\ud2b8\uc5d0 \ub9de\ub294 \uc0c1\ud0dc \uad00\ub9ac\ub97c \uace0\ubbfc\ud558\uc2dc\ub294\uac8c \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"21c73feb-f0bb-4e5c-9980-01ba9558a07a\\" id=\\"21c73feb-f0bb-4e5c-9980-01ba9558a07a\\">\ud3f0\ud2b8 \ucd5c\uc801\ud654\uc5d0 \ub300\ud55c \ubaa8\ub4e0 \uac83</h2><a href=\\"https://www.debugbear.com/blog/website-font-performance\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.debugbear.com/blog/website-font-performance</a><p data-notion-block-id=\\"cc2e1e6e-d109-4664-899c-b11a694085ce\\"><b>\uc2ec\uc724\uc12d</b>: \ucd5c\uc2e0 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ud3f0\ud2b8\ub97c \uc124\uc815\ud558\ub294 \ubc29\ubc95\uc744 \ubaa8\ub450 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud3f0\ud2b8 \ucd5c\uc801\ud654\uc5d0 \uad00\ub828\ub41c \uae00\uc740 \uc544\ub2c8\uc9c0\ub9cc OpenType\uc758 \uc5ed\uc0ac, \ud3f0\ud2b8 \ub80c\ub354\ub9c1 \ubc29\uc2dd, \uadf8\ub9ac\uace0 \ud65c\uc6a9 \ubc29\uc2dd\uacfc \uc0dd\ud0dc\uacc4\ub97c \uc815\ub9ac\ud55c <a href=\\"https://behdad.org/text2024/\\">2024\ub144 \ud14d\uc2a4\ud2b8 \ub80c\ub354\ub9c1 \ud604\ud669</a> \uae00\uc774 \uc788\uc73c\ub2c8 \uad00\uc2ec \uc788\uc73c\uba74 \ubcf4\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4. COLR \ud3ec\ub9f7\uc744 \ud65c\uc6a9\ud558\uac70\ub098(<a href=\\"https://blog.glyphdrawing.club/font-with-built-in-syntax-highlighting/\\">\ucee4\uc2a4\ud140 \ud3f0\ud2b8\ub85c syntax highlighting \uad6c\ud604</a>), \uac00\ubcc0 \ud3f0\ud2b8\ub97c \ud65c\uc6a9\ud574\uc57c \ud558\ub294 \uacbd\uc6b0(<code>font-feature-settings</code>)\ub3c4 \uc788\uc73c\ub2c8 \uac00\ubccd\uac8c \ubcf4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"3a70cc0d-c9a3-45e0-9bdc-35c4d98b5e95\\"><b>\uae40\ub300\uad00</b>: npm\uc5d0\uc11c \uc11c\ube59\ud558\ub294 \ud3f0\ud2b8(<a href=\\"https://github.com/fontsource/fontsource\\">FontSource</a>, \ud55c\uae00 \ud3f0\ud2b8\ub4e4\uc740 \ubaa8\ub450 \ub530\ub85c \uc788\uc74c), \ube44\uad50\uc801 \uc54c\ub824\uc9c0\uc9c0 \uc54a\uc740 API\uc778 <a href=\\"https://developer.mozilla.org/en-US/docs/Web/API/CSS_Font_Loading_API\\">Font Loader API</a>(\uc640 API\ub97c \ud65c\uc6a9\ud55c <a href=\\"https://github.com/bramstein/fontfaceobserver\\">FontFaceObserver</a>)\ub3c4 \uc788\uc73c\ub2c8 \ucc38\uace0\ud558\uc168\uc73c\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"d66e1e1e-5cb2-40b1-9893-16929f8a2d3e\\" id=\\"d66e1e1e-5cb2-40b1-9893-16929f8a2d3e\\"><code>@svg-use</code>\uac00 \ud574\uacb0\ud558\uace0\uc790 \ud558\ub294 \uac83</h2><a href=\\"https://fotis.xyz/posts/introducing-svg-use/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://fotis.xyz/posts/introducing-svg-use/</a><p data-notion-block-id=\\"d8351c59-a310-4a3f-b612-c2f3e801867b\\"><b>\uc2ec\uc724\uc12d</b>: CRA\ub85c \uac1c\ubc1c\ud558\ub358 \ubd84\uc774\ub77c\uba74 SVGR\uc744 \ub9ce\uc774 \ub9c8\uc8fc\ucce4\uc744 \uac83\uc774\uace0, \uc774\uc5d0 \ub300\ud55c \ubb38\uc81c\ub97c \ub9ce\uc774 \ub9c8\uc8fc\ucce4\uc744 \uac83\uc785\ub2c8\ub2e4. \uc774 \uae00\uc740 SVGR\uac19\uc740 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc778 SVG-in-JS\uc758 \ubb38\uc81c\uc810\uc744 \uc0b4\ud3b4\ubcf4\uace0, \ub2e4\ub978 \uc811\uadfc \ubc29\uc2dd\uacfc \ud568\uaed8 <code>@svg-use</code>\uac00 \uc774\ub97c \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"7209e06a-f90c-400f-883b-69e46dbb3b6e\\" id=\\"7209e06a-f90c-400f-883b-69e46dbb3b6e\\">Build Time \ud50c\ub7ec\uadf8\uc778 vs RSC</h2><a href=\\"https://codehike.org/blog/build-time-components\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://codehike.org/blog/build-time-components</a><p data-notion-block-id=\\"8bd0cad7-b417-4a12-8fcc-90b213952852\\">\ub9c8\ud06c\ub2e4\uc6b4\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c4 \uae00\uc774 Nextjs\uc5d0\uc11c \uc5b4\ub5a4 \uacfc\uc815\uc744 \uac70\uccd0 \ube4c\ub4dc\ub418\ub294 \uc9c0\uc640 Build-Time \ud50c\ub7ec\uadf8\uc778\uacfc RSC\uc758 \uc7a5\ub2e8\uc810\uc740 \uc5b4\ub5a4\uc9c0 \ube44\uad50\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub2e8\uc801\uc73c\ub85c SSG(\uc0c1\ud669\uc5d0 \ub530\ub77c ISR)\uacfc RSC \ubc29\uc2dd\uc744 \ube44\uad50\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/abdeee1c-f704-449c-9b9c-77f2d5f1714a#e974e7a8-9bb8-45cd-afc3-502c83efca65\\">Vercel\uc758 \ub80c\ub354\ub9c1 \uc124\uba85</a> \uae00\uacfc \uac19\uc774 \uc77d\uc73c\uba74 \uc88b\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"66a19971-b1ed-4859-9159-87e1af63725c\\" id=\\"66a19971-b1ed-4859-9159-87e1af63725c\\">\ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\ub97c \uc704\ud55c LLM</h2><a href=\\"https://edspencer.net/2024/9/2/easy-rag-for-typescript-and-react-apps\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://edspencer.net/2024/9/2/easy-rag-for-typescript-and-react-apps</a><p data-notion-block-id=\\"cae983a2-2de1-439c-b4cd-98bae4dd784e\\">\ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\uc758 \uad00\uc810\uc5d0\uc11c LLM\uc744 \uc0b4\ud3b4\ubcf4\uace0, \uc5b4\ub5bb\uac8c \ud65c\uc6a9\ud558\ub294\uc9c0 \uc9c4\ud589\ud558\ub294 \ud29c\ud1a0\ub9ac\uc5bc 3\ubd80\uc791 \uae00\uc785\ub2c8\ub2e4(\ubbf8\uc644\uc131). AI\uc5d0 \ub300\ud55c \uac1c\ub150\uc744 \uc798 \uc774\ud574\ud560 \uc218 \uc788\uac8c \uc124\uba85\ud574\uc8fc\ubbc0\ub85c \uac00\ubccd\uac8c \ubcfc\ub9cc\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"e54c04ce-d381-47c4-a9e7-3dfad6e7373a\\" id=\\"e54c04ce-d381-47c4-a9e7-3dfad6e7373a\\">CSS \uc791\uc131\ubc29\uc2dd \uac00\uc774\ub4dc(\ud558\ub098 \ube7c\uace0)</h2><a href=\\"https://www.alexchantastic.com/modern-css-authoring\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.alexchantastic.com/modern-css-authoring</a><p data-notion-block-id=\\"a011bf71-e6df-47eb-b2e0-428ffab0fea1\\">\uc77c\ubc18 CSS\uc640 \uc804\ucc98\ub9ac\uae30, CSS \ubaa8\ub4c8, CSS-in-JS\uae4c\uc9c0 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4(utility CSS\ub294 \uc5c6\uc2b5\ub2c8\ub2e4). \uac1c\ub150\uc744 \uac04\ub2e8\ud558\uac8c \uc124\uba85\ud558\ubbc0\ub85c \uac1c\ub150\uc744 \ubaa8\ub974\uc2dc\ub294 \ubd84\ub4e4\uaed8 \uad8c\uc7a5\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"87364325-d535-4c60-86e3-961cbe15a2e5\\" id=\\"87364325-d535-4c60-86e3-961cbe15a2e5\\">\uc560\ub2c8\uba54\uc774\uc158 \uc131\ub2a5 \uac00\uc774\ub4dc</h2><a href=\\"https://web.dev/explore/animations?hl=ko\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://web.dev/explore/animations?hl=ko</a><p data-notion-block-id=\\"41ee5b06-f407-46b9-997d-e341b7963683\\"><a href=\\"https://component-odyssey.com/articles/13-improving-performance-by-changing-two-lines-of-css\\">\uac04\ub2e8\ud55c \uc560\ub2c8\uba54\uc774\uc158 \uc131\ub2a5 \ucd5c\uc801\ud654 \uae00</a>\uc744 \ubcf4\uace0 \ucd94\ucc9c\ub4dc\ub9ac\ub294 \uc131\ub2a5 \ucd5c\uc801\ud654 \uac00\uc774\ub4dc \uae00\ub4e4\uc785\ub2c8\ub2e4. \ube0c\ub77c\uc6b0\uc800 \ub80c\ub354\ub9c1\uacfc CSS \uc560\ub2c8\uba54\uc774\uc158, JS \uc560\ub2c8\uba54\uc774\uc158 API\uae4c\uc9c0 \uc18c\uac1c\ud558\ubbc0\ub85c \uc560\ub2c8\uba54\uc774\uc158\uc744 \ub9cc\ub4e4\uace0\ud508 \ubd84\ub4e4\uc5d0\uac8c \uad8c\uc7a5\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"02e5f692-2234-437b-8ede-c28bde84bb48\\" id=\\"02e5f692-2234-437b-8ede-c28bde84bb48\\">3\ub300\uc7a5 \uadfc\ud669 \uc18c\uac1c</h2><a href=\\"https://blog.angular.dev/the-future-is-standalone-475d7edbc706\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.angular.dev/the-future-is-standalone-475d7edbc706</a><a href=\\"https://blog.vuejs.org/posts/vue-3-5\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.vuejs.org/posts/vue-3-5</a><a href=\\"https://vercel.com/blog/whats-new-in-react-19\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vercel.com/blog/whats-new-in-react-19</a><p data-notion-block-id=\\"7c301833-770a-4b53-b352-5225f6fc2bdb\\">\uc21c\uc11c\ub300\ub85c Angular\uc758 <code>NgModule</code> \uc5c6\uc774 \ucef4\ud3ec\ub10c\ud2b8 \uc81c\uc791\uc774 \uac00\ub2a5\ud558\ub2e4\ub294 \uae00, Vue 3.5\uc758 \uc131\ub2a5, \ud3b8\uc758\uc131 \uac1c\uc120 \uae00, React 19 \uae30\ub2a5 \uc18c\uac1c \uae00\uc785\ub2c8\ub2e4. UI \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc774 \ud06c\uac8c \ub2ec\ub77c\uc9c4 \uc810\uc740 \uc5c6\uc5b4 \uc9e7\uac8c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"afd27588-dc4c-42dd-8385-5e1968fc5087\\"></p>"}')}}]);